        'border-yellow-500': toast.type === 'warning',
        'border-blue-500': toast.type === 'info',
      }"
    >
      <div class="text-xl">
        {{ getIcon(toast.type) }}
      </div>
      <div class="flex-1">
        <div
          class="font-press text-[10px] mb-1"
          :class="{
            'text-red-400': toast.type === 'error',
