            'text-blue-400': toast.type === 'info',
          }"
        >
          {{ toast.title }}
        </div>
        <div class="font-mono text-xs text-white">
          {{ toast.message }}
        </div>
      </div>
      <button
        @click="remove(toast.id)"
        class="text-gray-500 hover:text-white font-mono"
      >
        x
      </button>
